// Extract Ghost webhook payload
const data = $input.first().json;
const post = data.body?.post?.current || data.post?.current;

if (!post || !post.id) {
  console.log('Received data:', JSON.stringify(data, null, 2));
  throw new Error('Ghost webhook payload missing post.current.id');
}

// Only process published posts
if (post.status !== 'published') {
  return [{ json: { skip: true, reason: `Post status is '${post.status}'` } }];
}

// Parse URL manually (n8n doesn't have URL constructor)
const urlMatch = post.url.match(/^(https?:\/\/[^\/]+)/);
const siteBase = urlMatch ? urlMatch[1] : '';
const hostnameMatch = post.url.match(/^https?:\/\/([^\/]+)/);
const hostname = hostnameMatch ? hostnameMatch[1] : '';
const siteSlug = hostname.split('.')[0];
const jobId = `${siteSlug}-${post.slug}`;

return [{
  json: {
    skip: false,
    postId: post.id,
    postSlug: post.slug,
    postTitle: post.title,
    postUrl: post.url,
    siteBase,
    siteSlug,
    jobId,
    timestamp: new Date().toISOString()
  }
}];

const item = $input.first().json;
const post = item.posts?.[0];

if (!post) {
  throw new Error('Could not fetch article from Ghost API');
}

// Clean up the plaintext
let text = post.plaintext || '';
text = text.replace(/\n{3,}/g, '\n\n').trim();

// Get metadata from previous node
const meta = $('Extract Post Metadata').first().json;

return [{
  json: {
    jobId: meta.jobId,
    siteSlug: meta.siteSlug,
    postTitle: post.title,
    postSlug: post.slug,
    articleText: text,
    wordCount: text.split(/\s+/).length
  }
}];

